functions.kdtree_build:
void kdtree_build(double *x, double *y, double *z, size_t count, kdtree **tree_ptr)
{
    size_t i;
    kdtree *tree = *tree_ptr;
    ((count > 1) ? (void)(0) : __assert_fail("count > 1", "kd3/kdtree.c", 142, __extension__ __PRETTY_FUNCTION__));
    if (!tree || tree->count != count)
    {
        if (tree)
            kdtree_delete(&tree);
        tree = malloc(sizeof(kdtree));
        ((tree != ((void *)0)) ? (void)(0)
                               : __assert_fail("tree != NULL", "kd3/kdtree.c", 150, __extension__ __PRETTY_FUNCTION__));
        *tree_ptr = tree;
        tree->count = count;
        tree->max_nodes = ((count - 1) * 2) + 1;
        tree->points = malloc(sizeof(struct data_point) * count);
        tree->node_data = malloc(sizeof(struct tree_node) * tree->max_nodes);
        ((tree->points != ((void *)0))
             ? (void)(0)
             : __assert_fail("tree->points != NULL", "kd3/kdtree.c", 158, __extension__ __PRETTY_FUNCTION__));
        ((tree->node_data != ((void *)0))
             ? (void)(0)
             : __assert_fail("tree->node_data != NULL", "kd3/kdtree.c", 159, __extension__ __PRETTY_FUNCTION__));
    }
    tree->next_node = 0;
    for (i = 0; i < count; i++)
    {
        tree->points[i].idx = i;
        tree->points[i].x = x[i];
        tree->points[i].y = y[i];
        tree->points[i].z = z[i];
    }
    tree->root = _build_kdtree(0, count - 1, 0, tree);
}

functions.kdtree_search:
void kdtree_search(kdtree *tree, kdtree_iterator **iter_ptr, double x, double y, double z, double apothem)
{
    ((apothem >= 0.0) ? (void)(0)
                      : __assert_fail("apothem >= 0.0", "kd3/kdtree.c", 184, __extension__ __PRETTY_FUNCTION__));
    kdtree_search_space(tree, iter_ptr, x - apothem, x + apothem, y - apothem, y + apothem, z - apothem, z + apothem);
}

functions.kdtree_search_space:
void kdtree_search_space(kdtree *tree, kdtree_iterator **iter_ptr, double x_min, double x_max, double y_min,
                         double y_max, double z_min, double z_max)
{
    kdtree_iterator *iter = *iter_ptr;
    struct space search_space;
    struct space domain;
    ((tree != ((void *)0)) ? (void)(0)
                           : __assert_fail("tree != NULL", "kd3/kdtree.c", 203, __extension__ __PRETTY_FUNCTION__));
    ((tree->root != ((void *)0))
         ? (void)(0)
         : __assert_fail("tree->root != NULL", "kd3/kdtree.c", 206, __extension__ __PRETTY_FUNCTION__));
    ((!_is_leaf_node(tree->root))
         ? (void)(0)
         : __assert_fail("!_is_leaf_node(tree->root)", "kd3/kdtree.c", 207, __extension__ __PRETTY_FUNCTION__));
    if (iter != ((void *)0))
        _iterator_reset(iter);
    else
    {
        iter = _iterator_new();
        *iter_ptr = iter;
    }
    search_space.dim[DIM_X].min = x_min;
    search_space.dim[DIM_X].max = x_max;
    search_space.dim[DIM_Y].min = y_min;
    search_space.dim[DIM_Y].max = y_max;
    search_space.dim[DIM_Z].min = z_min;
    search_space.dim[DIM_Z].max = z_max;
    domain.dim[DIM_X].min = -1.7976931348623157e+308;
    domain.dim[DIM_X].max = 1.7976931348623157e+308;
    domain.dim[DIM_Y].min = -1.7976931348623157e+308;
    domain.dim[DIM_Y].max = 1.7976931348623157e+308;
    domain.dim[DIM_Z].min = -1.7976931348623157e+308;
    domain.dim[DIM_Z].max = 1.7976931348623157e+308;
    _search_kdtree(tree, tree->root, 0, &search_space, &domain, iter);
}

